// The body checks for a nonzero count, a present string buffer with nonzero
// length, and a nonnull Object argument. After those guards it resolves both
// controlling players and the named template. Counter updates are conditional
// on distinct players and a resolved template; count reset and string release
// still occur when either condition fails. The owner identity remains opaque.
#include "StringInline.h"

class Player;
class ThingTemplate;

class Object
{
public:
	Player *getControllingPlayer(void) const;
};

class BfmeThingFactory
{
public:
	const ThingTemplate *findTemplate(const AsciiString &name);
};
extern BfmeThingFactory *TheThingFactory;

class ScoreKeeper
{
public:
	void addObjectCount(const ThingTemplate *tmpl, int count);
	void addObjectDestroyedCount(const ThingTemplate *tmpl, const Player *byPlayer, int count);
};

class BFMERetailAsciiString : public AsciiString
{
public:
	void releaseBuffer(void);
};


struct Rva0024E990Owner
{
	void rva0024e990(Object *other);

	unsigned char m_head08[8];
	Object *m_creatorObj;
	unsigned char m_gap[0x9bc - 8 - 4];
	int m_count;
	BFMERetailAsciiString m_name;
};

void Rva0024E990Owner::rva0024e990(Object *other)
{
	if ((unsigned int)m_count <= 0)
		return;

	BFMERetailAsciiString &name = m_name;
	char *buf = *(char **)&name;
	if (!buf)
		return;

	if (*(short *)(buf + 4) == 0)
		return;

	if (!other)
		return;

	Player *player1 = m_creatorObj->getControllingPlayer();
	const ThingTemplate *tmpl;
	Player *player2 = other->getControllingPlayer();
	tmpl = TheThingFactory->findTemplate(name);

	if (player1 != player2 && tmpl)
	{
		((ScoreKeeper *)((char *)player1 + 0x348))->addObjectCount(tmpl, m_count);
		((ScoreKeeper *)((char *)player2 + 0x348))->addObjectDestroyedCount(tmpl, player1, m_count);
	}

	m_count = 0;
	name.releaseBuffer();
}
